func (enc *IdentityEncoder) RuneToCharcode(r rune) (CharCode, bool) {
	if enc.toUnicode != nil {
		if cid, ok := enc.toUnicode.StringToCID(string(r)); ok && cid <= 0xffff {
			enc.usedGIDs.Write(uint16(cid))
			return CharCode(cid), true
		}
	}
	if r < 0 || r > 0xffff {
		return 0, false
	}
	enc.usedGIDs.Write(uint16(r))
	return CharCode(r), true
}

